function sortData(data: Person[], columns: TableColumnConfig<Person>[], sortState: TableSortState) {
  if (sortState.length === 0) return data;
  const sorted = [...data];
  sorted.sort((a, b) => {
    for (const {column, order} of sortState) {
      const col = columns.find(c => c.id === column);
      if (!col?.meta?.sort) continue;
      let result: number;
      const sortMeta = col.meta.sort;
      if (typeof sortMeta === 'function') {
        result = sortMeta(a, b);
      } else {
        const va = a[column as keyof Person];
        const vb = b[column as keyof Person];
        result = va === vb ? 0 : va > vb ? 1 : -1;
      }
      if (result !== 0) return order === 'asc' ? result : -result;
    }
    return 0;
  });
  return sorted;
}
```

